final View floatingContainer = findViewById(R.id.floating_container);
final EditText urlInput = (EditText)findViewById(R.id.video_url);
final android.webkit.WebView webView = (android.webkit.WebView)findViewById(R.id.web_player);
final View btnClose = findViewById(R.id.btn_close);
final View btnMake = findViewById(R.id.btn_make);

android.webkit.WebSettings ws = webView.getSettings();
ws.setJavaScriptEnabled(true);
ws.setDomStorageEnabled(true);
ws.setMediaPlaybackRequiresUserGesture(false);

// টাচ করে স্ক্রল করা পুরোপুরি ব্লক
webView.setOnTouchListener(new View.OnTouchListener() {
    @Override
    public boolean onTouch(View v, android.view.MotionEvent event) {
        return (event.getAction() == android.view.MotionEvent.ACTION_MOVE);
    }
});

webView.setWebViewClient(new android.webkit.WebViewClient() {
    @Override
    public void onPageFinished(android.webkit.WebView view, String url) {
        // এই শক্তিশালী CSS টি শুধু ভিডিও প্লেয়ার বাদে সব মুছে ফেলবে
        String css = "header, footer, #header-bar, .ytm-app-bar, " +
                     "ytm-slim-video-metadata-section-renderer, " + /* টাইটেল, সাবস্ক্রাইব গুম */
                     "ytm-item-section-renderer, #related, #comments, " + /* রিলেটেড ভিডিও গুম */
                     ".ytp-watermark, .ytp-chrome-top, .ytp-gradient-bottom, .ytp-gradient-top " +
                     "{ display: none !important; } " +
                     "body { overflow: hidden !important; background: black !important; } " +
                     "video { width: 100vw !important; height: auto !important; }";

        view.evaluateJavascript("(function() { " +
                    "var style = document.createElement('style'); " +
                    "style.innerHTML = '" + css + "'; " +
                    "document.head.appendChild(style); " +
                    "window.scrollTo(0,0); " + 
                    "})()", null);
    }
});

btnMake.setOnClickListener(new View.OnClickListener() {
    @Override
    public void onClick(View v) {
        String url = urlInput.getText().toString();
        if(url.trim().isEmpty()) return;

        String vId = "";
        try {
            if (url.contains("v=")) vId = url.split("v=")[1].split("&")[0];
            else if (url.contains("shorts/")) vId = url.split("shorts/")[1].split("\\?")[0];
            else vId = url.substring(url.lastIndexOf("/") + 1).split("\\?")[0];
        } catch(Exception e) { vId = ""; }

        floatingContainer.setVisibility(View.VISIBLE);
        webView.loadUrl("https://m.youtube.com/watch?v=" + vId);
    }
});

btnClose.setOnClickListener(new View.OnClickListener() {
    @Override
    public void onClick(View v) {
        floatingContainer.setVisibility(View.GONE);
        webView.loadUrl("about:blank"); // ভিডিও বন্ধ করতে
    }
});
